app.get('/api/dashboard',auth,tenant,async(req,res)=>{
  const bid=await getBiz(req); const p=[bid];
  const qs=await Promise.all([
    pool.query('SELECT count(*)::int v FROM products WHERE business_id=$1 AND active=true',p),
    pool.query("SELECT count(*)::int v FROM sales WHERE business_id=$1 AND created_at::date=current_date",p),
    pool.query("SELECT coalesce(sum(total),0)::numeric v FROM sales WHERE business_id=$1 AND created_at::date=current_date",p),
    pool.query('SELECT count(*)::int v FROM products WHERE business_id=$1 AND stock<=reorder_level',p),
    pool.query("SELECT coalesce(sum(total),0)::numeric v FROM sales WHERE business_id=$1 AND created_at>=date_trunc('month',now())",p),
    pool.query("SELECT coalesce(sum(si.line_total-(si.unit_cost*si.qty)),0)::numeric v FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=$1 AND s.created_at::date=current_date",p),
    pool.query("SELECT coalesce(sum(amount),0)::numeric v FROM expenses WHERE business_id=$1 AND expense_date=current_date AND accounting_treatment='operating_expense'",p),
    pool.query("SELECT payment_method,coalesce(sum(total),0)::numeric total FROM sales WHERE business_id=$1 AND created_at::date=current_date GROUP BY payment_method ORDER BY total DESC",p),
    pool.query("SELECT si.product_name,sum(si.qty)::numeric qty,sum(si.line_total)::numeric total FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=$1 AND s.created_at>=now()-interval '30 days' GROUP BY si.product_name ORDER BY qty DESC LIMIT 5",p),
    pool.query("SELECT receipt_no,total,payment_method,cashier,created_at FROM sales WHERE business_id=$1 ORDER BY id DESC LIMIT 8",p),
    pool.query('SELECT name,currency,status,trial_ends_at FROM businesses WHERE id=$1',p)
  ]);
  res.json({products:qs[0].rows[0].v,salesToday:qs[1].rows[0].v,revenueToday:qs[2].rows[0].v,lowStock:qs[3].rows[0].v,revenueMonth:qs[4].rows[0].v,grossProfitToday:qs[5].rows[0].v,expensesToday:qs[6].rows[0].v,paymentBreakdown:qs[7].rows,bestSellers:qs[8].rows,recentSales:qs[9].rows,business:qs[10].rows[0]});
});
