app.post('/api/purchase-orders',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const {supplierId,branchId=null,items=[],notes=null}=req.body||{};if(!supplierId||!Array.isArray(items)||!items.length)return res.status(400).json({error:'Supplier and at least one item are required'});const clean=items.map(x=>({productId:Number(x.productId),qty:Number(x.qty),unitCost:Number(x.unitCost||0)})).filter(x=>x.productId&&x.qty>0&&x.unitCost>=0);if(clean.length!==items.length)return res.status(400).json({error:'Every purchase item needs a valid product, quantity and cost'});const client=await pool.connect();try{await client.query('BEGIN');const supplier=await client.query('SELECT id,name FROM suppliers WHERE id=$1 AND business_id=$2',[supplierId,bid]);if(!supplier.rowCount)throw new Error('Supplier not found');let branch=branchId?Number(branchId):null;if(branch){const b=await client.query('SELECT id FROM branches WHERE id=$1 AND business_id=$2 AND active=true',[branch,bid]);if(!b.rowCount)throw new Error('Branch not found')}else{const b=await client.query('SELECT id FROM branches WHERE business_id=$1 AND active=true ORDER BY id LIMIT 1',[bid]);branch=b.rows[0]?.id||null}const productIds=clean.map(x=>x.productId);const allowed=await client.query('SELECT sp.product_id,p.name FROM supplier_products sp JOIN products p ON p.id=sp.product_id WHERE sp.business_id=$1 AND sp.supplier_id=$2 AND sp.active=true AND p.active=true AND sp.product_id=ANY($3::bigint[])',[bid,supplierId,productIds]);if(allowed.rowCount!==new Set(productIds).size)throw new Error('Purchase contains a product not registered for this supplier');const names=new Map(allowed.rows.map(x=>[Number(x.product_id),x.name]));const total=clean.reduce((n,x)=>n+x.qty*x.unitCost,0),poNo=makeDocNo('PO');const po=await client.query("INSERT INTO purchase_orders(business_id,branch_id,supplier_id,po_no,status,notes,subtotal,total,created_by) VALUES($1,$2,$3,$4,'draft',$5,$6,$6,$7) RETURNING *",[bid,branch,supplierId,poNo,notes,total,req.user.name]);for(const x of clean)await client.query('INSERT INTO purchase_order_items(purchase_order_id,product_id,product_name,qty_ordered,unit_cost,line_total) VALUES($1,$2,$3,$4,$5,$6)',[po.rows[0].id,x.productId,names.get(x.productId),x.qty,x.unitCost,x.qty*x.unitCost]);await client.query('COMMIT');await audit(req.user,bid,'create','purchase_order',po.rows[0].id,{poNo,supplierId,total});res.json(po.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/purchase-orders/:id/submit',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),comment=req.body?.comment||null;const client=await pool.connect();try{await client.query('BEGIN');const po=await client.query("SELECT po.*,s.name supplier_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id WHERE po.id=$1 AND po.business_id=$2 FOR UPDATE",[id,bid]);if(!po.rowCount)throw new Error('Purchase order not found');if(!['draft','rejected'].includes(po.rows[0].status))throw new Error('Only draft or rejected purchase orders can be submitted');const target=await approvalTarget(client,bid,'purchase_order');await client.query("UPDATE purchase_orders SET status='pending_approval',approval_status='pending',approval_comment=$1,updated_at=now(),rejected_by=null,rejected_at=null WHERE id=$2",[comment,id]);const ar=await client.query("INSERT INTO approval_requests(business_id,section,action_type,entity_type,entity_id,reference_no,title,amount,requested_by_user_id,requested_by_name,approver_user_id,approver_role,status,request_comment) VALUES($1,'Purchasing','purchase_order','purchase_order',$2,$3,$4,$5,$6,$7,$8,$9,'pending',$10) RETURNING *",[bid,id,po.rows[0].po_no,'Purchase Order '+po.rows[0].po_no+' · '+po.rows[0].supplier_name,po.rows[0].total,req.user.id,req.user.name,target.approverUserId,target.approverRole,comment]);await client.query('COMMIT');await audit(req.user,bid,'request_approval','purchase_order',id,{approvalRequestId:ar.rows[0].id,poNo:po.rows[0].po_no});res.json({purchaseOrder:{...po.rows[0],status:'pending_approval',approval_status:'pending'},approval:ar.rows[0]})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/purchase-orders/:id/receive',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const {items=[],supplierReference=null,notes=null}=req.body||{};if(!Array.isArray(items)||!items.length)return res.status(400).json({error:'At least one received item is required'});const clean=items.map(x=>({itemId:Number(x.itemId),qty:Number(x.qty),unitCost:Number(x.unitCost)})).filter(x=>x.itemId&&x.qty>0&&x.unitCost>=0);if(clean.length!==items.length)return res.status(400).json({error:'Invalid received item'});const client=await pool.connect();try{await client.query('BEGIN');const po=await client.query("SELECT * FROM purchase_orders WHERE id=$1 AND business_id=$2 FOR UPDATE",[id,bid]);if(!po.rowCount)throw new Error('Purchase order not found');if(!['ordered','partial'].includes(po.rows[0].status))throw new Error('Purchase order must be submitted before receiving');const itemIds=clean.map(x=>x.itemId);const rows=await client.query("SELECT poi.*,p.stock,p.cost FROM purchase_order_items poi JOIN products p ON p.id=poi.product_id WHERE poi.purchase_order_id=$1 AND poi.id=ANY($2::bigint[]) FOR UPDATE OF poi,p",[id,itemIds]);if(rows.rowCount!==new Set(itemIds).size)throw new Error('One or more receipt items are invalid');const map=new Map(rows.rows.map(x=>[Number(x.id),x]));for(const x of clean){const row=map.get(x.itemId),outstanding=Number(row.qty_ordered)-Number(row.qty_received);if(x.qty>outstanding+0.000001)throw new Error('Received quantity exceeds outstanding quantity for '+row.product_name)}const receivingLocationId=await ensureDefaultLocation(client,bid,po.rows[0].branch_id);const grnNo=makeDocNo('GRN');const grn=await client.query('INSERT INTO goods_receipts(business_id,branch_id,purchase_order_id,supplier_id,grn_no,supplier_reference,notes,received_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[bid,po.rows[0].branch_id,id,po.rows[0].supplier_id,grnNo,supplierReference,notes,req.user.name]);for(const x of clean){const row=map.get(x.itemId),before=Number(row.stock),after=before+x.qty;await client.query('INSERT INTO goods_receipt_items(goods_receipt_id,purchase_order_item_id,product_id,qty_received,unit_cost,line_total) VALUES($1,$2,$3,$4,$5,$6)',[grn.rows[0].id,row.id,row.product_id,x.qty,x.unitCost,x.qty*x.unitCost]);await client.query('UPDATE purchase_order_items SET qty_received=qty_received+$1,unit_cost=$2,line_total=qty_ordered*$2 WHERE id=$3',[x.qty,x.unitCost,row.id]);await inventoryBalanceChange(client,{bid,locationId:receivingLocationId,productId:Number(row.product_id),delta:x.qty,unitCost:x.unitCost,movementType:'purchase_receipt',referenceType:'GRN',referenceId:Number(grn.rows[0].id),referenceNo:grnNo,notes,userName:req.user.name,toLocationId:receivingLocationId,updateProductCost:true})}const grnTotal=clean.reduce((n,x)=>n+(x.qty*x.unitCost),0);await client.query("INSERT INTO expenses(business_id,category,description,amount,expense_date,reference_no,source_type,source_id,auto_generated,accounting_treatment,status,supplier_id,purchase_order_id,grn_id) VALUES($1,'Inventory Purchase',$2,$3,current_date,$4,'GRN',$5,true,'inventory_asset','posted',$6,$7,$5) ON CONFLICT(business_id,source_type,source_id) WHERE source_type IS NOT NULL AND source_id IS NOT NULL DO NOTHING",[bid,'Inventory received against '+po.rows[0].po_no,grnTotal,grnNo,grn.rows[0].id,po.rows[0].supplier_id,id]);const remain=await client.query('SELECT count(*)::int v FROM purchase_order_items WHERE purchase_order_id=$1 AND qty_received<qty_ordered',[id]);const status=remain.rows[0].v===0?'received':'partial';await client.query('UPDATE purchase_orders SET status=$1,updated_at=now() WHERE id=$2',[status,id]);await client.query('COMMIT');await audit(req.user,bid,'receive','goods_receipt',grn.rows[0].id,{grnNo,purchaseOrderId:id,status});res.json({grn:grn.rows[0],purchaseOrderStatus:status})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
